import fs from "node:fs";
import path from "node:path";

import { getUploadedOptimizedImages } from "../src/lib/optimizedImagesApi";

const outFile = path.join(
  process.cwd(),
  "src/data/optimizedImages.api.generated.ts",
);

async function main() {
  const images = await getUploadedOptimizedImages();
  if (images === null) {
    console.warn(
      "The API has no /v1/images yet; writing an empty uploaded image catalog.",
    );
  }
  const source = `/* eslint-disable */
// Generated by scripts/compile-optimized-images.ts from the API — do not edit by hand.
import type { OptimizedImageEntry } from "../lib/optimizedImageSources";

export const uploadedOptimizedImages: Record<string, OptimizedImageEntry> = ${JSON.stringify(images ?? {}, null, 2)};
`;
  fs.writeFileSync(outFile, source, "utf8");
  console.log(
    `Compiled ${Object.keys(images ?? {}).length} uploaded optimized images from the API → ${outFile}`,
  );
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});
